IF ISNULL(JSON_VALUE(@r,N'$.status'),N'')<>N'COMPILED' OR ISNULL(JSON_VALUE(@r,N'$.documentDigest'),N'')<>N'sha256:80a4daab4d372f2a4025313631beb63bb96309f0f200268da49b88ab46ac3756'
